#pragma config(Motor, port1, testMotor, tmotorVex393_HBridge, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
ENGR 10 Week 1 - Practice program 2
Gradually speeds the motor up to forward maximum (127), then slows down, reverses,
and speeds up to reverse maximum (-127), then back again - swinging forever.
*/
task main()
{
	int speed = 0;
	int step = 1;            // +1 = speeding up forward, -1 = heading toward reverse

	while(true)
	{
		motor[testMotor] = speed;
		wait1Msec(40);
		speed = speed + step;

		if(speed >= 127)     // reached forward maximum - start going the other way
		{
			speed = 127;
			step = -1;
		}
		if(speed <= -127)    // reached reverse maximum - start going forward again
		{
			speed = -127;
			step = 1;
		}
	}
}
